import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import * as parser from '../../src/lib/import/framing-plan/parse'

const dir = 'tests/fixtures/section-import/textitems'
const files = readdirSync(dir).filter((file) => file.endsWith('.json')).sort()
if (files.length !== 36) throw new Error(`Expected 36 pages, got ${files.length}`)
const pages = files.map((file) => {
  const fixture = JSON.parse(readFileSync(`${dir}/${file}`, 'utf8'))
  const output = parser.parseFramingPlan({ ...fixture.page, items: fixture.items })
  const debug = (parser as any).__step0Measurements?.splice(0) ?? []
  return { file, fixture_source: fixture.source, output, debug }
})
writeFileSync(process.argv[2], JSON.stringify(pages, null, 2) + '\n')
console.log(JSON.stringify({ pages: pages.length, grid_pages: pages.filter((p) => p.output.grids.length).length, block_pages: pages.filter((p) => p.output.blocks.length).length }))

import hashlib
import json
from pathlib import Path
import subprocess

root = Path.cwd()
work = root / 'tmp/phase42-step0'
parser = root / 'src/lib/import/framing-plan/parse.ts'
original_bytes = parser.read_bytes()
original = original_bytes.decode('utf-8').replace('\r\n', '\n')
(work / 'original-parse.ts.txt').write_bytes(original_bytes)

def replace_once(text, before, after):
    assert text.count(before) == 1, (before, text.count(before))
    return text.replace(before, after)

def run(name):
    result = subprocess.run(['npx.cmd', 'tsx', 'tmp/phase42-step0/run.ts', f'tmp/phase42-step0/{name}.json'], capture_output=True, text=True, encoding='utf-8')
    print(name, result.returncode, result.stdout.strip(), flush=True)
    if result.returncode:
        print(result.stderr)
        raise RuntimeError(name)
    return json.loads((work / f'{name}.json').read_text(encoding='utf-8'))

def instrument(text):
    text = replace_once(text, '      dimensions.push({\n', '      dimensions.push({\n        __step0Text: normalizedText,\n')
    replacements = [
        ('''    return {
      ...sequence,
      direction: [...sequence.letters][0],
      spansMm: selected.solution.spans.map((span) => span.valueMm),
      scalePtPerMm: selected.solution.scalePtPerMm,
      totalConfirmed: true,
    }''', '''    return __step0Remember({
      ...sequence,
      direction: [...sequence.letters][0],
      spansMm: selected.solution.spans.map((span) => span.valueMm),
      scalePtPerMm: selected.solution.scalePtPerMm,
      totalConfirmed: true,
    }, sequence, selected.solution.spans, 0)'''),
        ('''    return {
      ...sequence,
      direction: [...sequence.letters][0],
      axes: sequence.axes.slice(first.firstIndex, first.lastIndex + 1),
      spansMm: solution.spans
        .slice(first.firstIndex, first.lastIndex)
        .map((span) => span.valueMm),
      scalePtPerMm: solution.scalePtPerMm,
      totalConfirmed: true,
    }''', '''    return __step0Remember({
      ...sequence,
      direction: [...sequence.letters][0],
      axes: sequence.axes.slice(first.firstIndex, first.lastIndex + 1),
      spansMm: solution.spans
        .slice(first.firstIndex, first.lastIndex)
        .map((span) => span.valueMm),
      scalePtPerMm: solution.scalePtPerMm,
      totalConfirmed: true,
    }, sequence, solution.spans.slice(first.firstIndex, first.lastIndex), first.firstIndex)'''),
        ('''  return {
    ...sequence,
    direction: [...sequence.letters][0],
    spansMm: selected.spans.map((span) => span.valueMm),
    scalePtPerMm: selected.scalePtPerMm,
    totalConfirmed: false,
  }''', '''  return __step0Remember({
    ...sequence,
    direction: [...sequence.letters][0],
    spansMm: selected.spans.map((span) => span.valueMm),
    scalePtPerMm: selected.scalePtPerMm,
    totalConfirmed: false,
  }, sequence, selected.spans, 0)'''),
        ('''function gridCandidate(sequence: DirectedSequence): PlanGridCandidate {
  return {
    direction: sequence.direction,
    axes: sequence.axes,
    spansMm: sequence.spansMm,
    scalePtPerMm: sequence.scalePtPerMm,
    totalConfirmed: sequence.totalConfirmed,
  }
}''', '''function gridCandidate(sequence: DirectedSequence): PlanGridCandidate {
  const candidate = {
    direction: sequence.direction,
    axes: sequence.axes,
    spansMm: sequence.spansMm,
    scalePtPerMm: sequence.scalePtPerMm,
    totalConfirmed: sequence.totalConfirmed,
  }
  __step0GridSequences.set(candidate, sequence)
  return candidate
}'''),
        ('  return { grids, blocks, issues }', '''  const result = { grids, blocks, issues }
  __step0Measurements.push(__step0Measure(result, dimensions))
  return result'''),
    ]
    for before, after in replacements:
        text = replace_once(text, before, after)
    return text + (work / 'instrumentation.ts.txt').read_text(encoding='utf-8')

try:
    baseline = run('baseline15')
    for tolerance in [4, 6, 15, 30, 40]:
        parser.write_text(replace_once(original, 'const MIDPOINT_TOLERANCE_PT = 15', f'const MIDPOINT_TOLERANCE_PT = {tolerance}'), encoding='utf-8', newline='')
        run(f'sweep{tolerance}')
    parser.write_text(instrument(original), encoding='utf-8', newline='')
    measured = run('measured15')
    assert all(a['output'] == b['output'] for a, b in zip(baseline, measured)), 'Instrumentation changed output'
finally:
    parser.write_bytes(original_bytes)
    assert parser.read_bytes() == original_bytes
    print('parser restored byte-for-byte', hashlib.sha256(original_bytes).hexdigest(), flush=True)

const __step0Selections = new WeakMap()
const __step0GridSequences = new WeakMap()
export const __step0Measurements: any[] = []
function __step0Remember(result: any, original: any, spans: any[], start: number) {
  __step0Selections.set(result.axes, { original, spans, start })
  return result
}
function __step0Measure(parsed: any, dimensions: any[]) {
  const sequences = [...new Set([
    ...parsed.grids,
    ...parsed.blocks.flatMap((block: any) => [block.xGrid, block.yGrid]),
  ].map((grid: any) => __step0GridSequences.get(grid)))]
  const rows: any[] = []
  for (const [sequenceIndex, sequence] of sequences.entries()) {
    const trace = __step0Selections.get(sequence.axes)
    if (!trace || trace.spans.length !== sequence.spansMm.length) throw new Error('Missing trace')
    const used = new Set(trace.spans)
    for (let index = 0; index < trace.spans.length; index++) {
      const span = trace.spans[index]
      if (span.valueMm !== sequence.spansMm[index]) throw new Error('Span mismatch')
      const originalIndex = trace.start + index
      const bands = [...new Set([
        ...(trace.original.axisAcrossOptions[originalIndex] ?? []),
        ...(trace.original.axisAcrossOptions[originalIndex + 1] ?? []),
      ])]
      const along = sequence.alongKey
      const across = along === 'x' ? 'y' : 'x'
      const axisPositions = [sequence.axes[index].positionPt, sequence.axes[index + 1].positionPt]
      const midpoint = (axisPositions[0] + axisPositions[1]) / 2
      const inWindow = (token: any) => bands.some((band: any) => Math.abs(token[across] - band) <= DIMENSION_WINDOW_PT)
      const entry = (token: any) => ({
        value_pt: Math.abs(token[along] - midpoint),
        direction: sequence.direction,
        along_key: along,
        axis_labels: [sequence.axes[index].label, sequence.axes[index + 1].label],
        dimension_text: token.__step0Text,
        dimension_value_mm: token.valueMm,
        dimension_token_index: dimensions.indexOf(token),
        dimension_center_pt: { x: token.x, y: token.y },
        axis_positions_pt: axisPositions,
        midpoint_pt: midpoint,
        across_options_pt: bands,
        across_distance_pt: Math.min(...bands.map((band: any) => Math.abs(token[across] - band))),
        total_confirmed: sequence.totalConfirmed,
        sequence_index: sequenceIndex,
        span_index: index,
      })
      if (!inWindow(span) || Math.abs(span[along] - midpoint) > MIDPOINT_TOLERANCE_PT) throw new Error('Invalid accepted span')
      const competitors = dimensions.filter((token) => !used.has(token) && inWindow(token)).map(entry).sort((a, b) => a.value_pt - b.value_pt || a.dimension_token_index - b.dimension_token_index)
      const perSpanCompetitors = dimensions.filter((token) => token !== span && inWindow(token)).map(entry).sort((a, b) => a.value_pt - b.value_pt || a.dimension_token_index - b.dimension_token_index)
      rows.push({
        accepted: entry(span),
        competing: competitors[0] ?? null,
        competing_distinct_value: competitors.find((item) => item.dimension_value_mm !== span.valueMm) ?? null,
        competing_per_span: perSpanCompetitors[0] ?? null,
        competitors_in_window: competitors.length,
        competitors_within_tolerance: competitors.filter((item) => item.value_pt <= MIDPOINT_TOLERANCE_PT).length,
        accepted_sequence_token_indices: trace.spans.map((token: any) => dimensions.indexOf(token)),
      })
    }
  }
  return { sequence_count: sequences.length, rows }
}
